@import '../../utils/forced-colors.css';
@import '../../utils/visually-hidden.css';

:host {
  display: block;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  -webkit-user-select: none;
  user-select: none;
}

.questionnaire {
  display: grid;
  gap: var(--dimension-space-150);
  width: 100%;
  padding: var(--dimension-space-200);
  border-radius: var(--dimension-radius-125);
  background: var(--color-background-primary);
  box-shadow: var(--effect-elevation-elevated-md);
  box-sizing: border-box;
}

.questionnaire--answered {
  gap: var(--dimension-space-100);
  padding: var(--dimension-space-150);
  background: var(--color-background-secondary);
  box-shadow: none;
}

.questionnaire--preparing {
  align-items: center;
  grid-template-columns: auto minmax(0, 1fr);
}

.questionnaire__header,
.questionnaire__actions,
.questionnaire__actions-leading,
.questionnaire__error,
.questionnaire__submission-error {
  display: flex;
  align-items: center;
}

.questionnaire__header,
.questionnaire__actions {
  justify-content: space-between;
  gap: var(--dimension-space-100);
}

.questionnaire__body,
.questionnaire__prompt,
.questionnaire__choices,
.questionnaire__single-choice,
.questionnaire__multiple-choice,
.questionnaire__other-choice,
.questionnaire__summary,
.questionnaire__summary li {
  display: grid;
}

.questionnaire__body,
.questionnaire__prompt,
.questionnaire__choices,
.questionnaire__single-choice,
.questionnaire__multiple-choice,
.questionnaire__other-choice {
  gap: var(--dimension-space-100);
}

.questionnaire__choices {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

ds-radio,
ds-checkbox {
  width: 100%;
  min-width: 0;
}

.questionnaire__other-input,
.questionnaire__text-input {
  width: 100%;
  padding: var(--dimension-space-100);
  border: var(--dimension-stroke-width-012) solid var(--color-border-secondary);
  border-radius: var(--dimension-radius-050);
  outline: none;
  background: var(--color-background-primary);
  color: var(--color-foreground-primary);
  font-family: var(--typography-font-family-ui);
  font-size: var(--typography-fontsize-md);
  font-weight: var(--typography-weight-regular);
  line-height: var(--typography-lineheight-md);
  letter-spacing: var(--typography-letterspacing-negative-half);
  box-sizing: border-box;
  -webkit-user-select: text;
  user-select: text;
}

.questionnaire__other-input {
  width: calc(100% - var(--dimension-size-500));
  margin-inline-start: var(--dimension-size-500);
}

.questionnaire__text-input {
  min-height: calc(var(--typography-lineheight-md) * 4 + var(--dimension-space-200));
  resize: vertical;
}

.questionnaire__other-input:focus,
.questionnaire__text-input:focus {
  border-color: var(--color-border-bold-brand);
  box-shadow: inset 0 0 0 var(--dimension-stroke-width-018)
    var(--color-border-bold-brand);
}

.questionnaire__other-input[aria-invalid='true'],
.questionnaire__text-input[aria-invalid='true'] {
  border-color: var(--color-border-bold-negative);
}

.questionnaire__error,
.questionnaire__submission-error {
  gap: var(--dimension-space-050);
  color: var(--color-foreground-bold-negative);
}

.questionnaire__submission-error {
  padding: var(--dimension-space-075);
  border-radius: var(--dimension-radius-050);
  background: var(--color-background-faint-negative);
}

.questionnaire__actions-leading {
  flex-wrap: wrap;
  gap: var(--dimension-space-075);
}

.questionnaire__action-item {
  width: fit-content;
  max-width: 100%;
}

.questionnaire textarea:disabled {
  color: var(--color-foreground-tertiary);
  cursor: default;
  opacity: 1;
}

.questionnaire__summary {
  gap: var(--dimension-space-100);
  margin: 0;
  padding: 0;
  list-style: none;
}

.questionnaire__summary li {
  gap: var(--dimension-space-025);
}

@media (max-width: 480px) {
  .questionnaire {
    padding: var(--dimension-space-150);
  }

  .questionnaire__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .questionnaire__actions-leading {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
  }

  .questionnaire__action-item,
  .questionnaire__action-item--primary {
    width: 100%;
  }
}

@media (forced-colors: active) {
  .questionnaire {
    border: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    box-shadow: none;
  }

  .questionnaire__other-input[aria-invalid='true'],
  .questionnaire__text-input[aria-invalid='true'] {
    outline: var(--dimension-stroke-width-025) dashed var(--ds-forced-color-content);
  }

  .questionnaire__submission-error {
    border: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    background: var(--ds-forced-color-surface);
  }

  .questionnaire input:disabled,
  .questionnaire textarea:disabled {
    color: var(--ds-forced-color-disabled);
  }
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Method,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import type {
  AgentQuestion,
  AgentQuestionAnswer,
  AgentQuestionnaireAnswerEventDetail,
  AgentQuestionnaireCancelEventDetail,
  AgentQuestionnaireLabels,
  AgentQuestionnaireStatus,
} from '../conversation-types';
import {
  createQuestionnaireDrafts,
  formatQuestionAnswer,
  normalizeQuestionAnswer,
  validateQuestionDraft,
} from './agent-questionnaire-model';
import type {
  AgentQuestionDraft,
  AgentQuestionDrafts,
} from './agent-questionnaire-model';

const DEFAULT_LABELS: AgentQuestionnaireLabels = {
  progress: 'Question {current} of {total}',
  previous: 'Previous',
  next: 'Next',
  answer: 'Answer',
  skip: 'Skip',
  cancel: 'Cancel',
  other: 'Other',
  otherPlaceholder: 'Enter another answer',
  preparing: 'Preparing questions…',
};

let questionnaireId = 0;

@Component({
  tag: 'ds-agent-questionnaire',
  styleUrl: 'AgentQuestionnaire.css',
  scoped: true,
})
export class AgentQuestionnaire {
  @Element() el!: HTMLElement;

  @Prop() requestId!: string;
  @Prop() questions!: AgentQuestion[];
  @Prop() answers: AgentQuestionAnswer[] = [];
  @Prop() status: AgentQuestionnaireStatus = 'ready';
  @Prop() errorMessage?: string;
  @Prop() allowCancel: boolean = false;
  @Prop() labels?: Partial<AgentQuestionnaireLabels>;

  @Event() dsAnswer!: EventEmitter<AgentQuestionnaireAnswerEventDetail>;
  @Event() dsCancel!: EventEmitter<AgentQuestionnaireCancelEventDetail>;

  @State() private currentStep = 0;
  @State() private drafts: AgentQuestionDrafts = {};
  @State() private validation: Record<string, string> = {};

  private readonly instanceId = ++questionnaireId;
  private readonly otherValue = `__ds-agent-questionnaire-other-${this.instanceId}`;
  private answerPending = false;
  private resetScheduled = false;
  private draftRequestId?: string;
  private answersSnapshot: AgentQuestionAnswer[] = [];
  private waitingForRequestAnswers = false;

  componentWillLoad() {
    this.draftRequestId = this.requestId;
    this.answersSnapshot = this.answers;
    this.resetDraft();
  }

  @Watch('requestId')
  @Watch('questions')
  @Watch('answers')
  handleQuestionnaireInputChange() {
    this.scheduleDraftReset();
  }

  @Watch('status')
  handleStatusChange(status: AgentQuestionnaireStatus) {
    if (status !== 'submitting') this.answerPending = false;
  }

  @Method()
  async setFocus(): Promise<void> {
    this.focusCurrentControl();
  }

  private get copy(): AgentQuestionnaireLabels {
    return { ...DEFAULT_LABELS, ...this.labels };
  }

  private get disabled(): boolean {
    return this.status === 'submitting';
  }

  private resetDraft(answers = this.answers) {
    this.currentStep = 0;
    this.drafts = createQuestionnaireDrafts(this.questions ?? [], answers ?? []);
    this.validation = {};
    this.answerPending = false;
  }

  private scheduleDraftReset() {
    if (this.resetScheduled) return;
    this.resetScheduled = true;
    queueMicrotask(() => {
      this.resetScheduled = false;
      const requestChanged = this.requestId !== this.draftRequestId;
      const answersChanged = this.answers !== this.answersSnapshot;
      if (requestChanged && !answersChanged) {
        this.waitingForRequestAnswers = true;
      } else if (answersChanged) {
        this.waitingForRequestAnswers = false;
      }
      this.resetDraft(this.waitingForRequestAnswers ? [] : this.answers);
      this.draftRequestId = this.requestId;
      this.answersSnapshot = this.answers;
    });
  }

  private focusCurrentControl(preferInvalid = false) {
    const focus = () => {
      const invalidControl = preferInvalid
        ? this.el.querySelector<HTMLElement>(
            '[data-question-control][aria-invalid="true"]:not([disabled])',
          )
        : null;
      const control = invalidControl ??
        this.el.querySelector<HTMLElement>(
          '[data-question-control]:not([disabled]):not([is-inactive])',
        );
      const action = this.el.querySelector<HTMLElement>(
        '[data-question-action]:not([is-inactive]):not([is-loading])',
      );
      const target = (control ?? action) as
        | (HTMLElement & { setFocus?: () => Promise<void> })
        | null;
      if (target?.setFocus) void target.setFocus();
      else target?.focus();
    };
    focus();
    requestAnimationFrame(focus);
    setTimeout(focus, 0);
  }

  private updateDraft(questionId: string, update: Partial<AgentQuestionDraft>) {
    const previous = this.drafts[questionId] ?? {
      value: '',
      otherSelected: false,
      otherText: '',
      skipped: false,
    };
    this.drafts = {
      ...this.drafts,
      [questionId]: { ...previous, ...update, skipped: false },
    };
    if (this.validation[questionId]) {
      const { [questionId]: _removed, ...rest } = this.validation;
      this.validation = rest;
    }
  }

  private validate(question: AgentQuestion): boolean {
    const message = validateQuestionDraft(question, this.drafts[question.id]);
    if (!message) return true;
    this.validation = { ...this.validation, [question.id]: message };
    this.focusCurrentControl(true);
    return false;
  }

  private move(step: number) {
    this.currentStep = Math.min(Math.max(step, 0), this.questions.length - 1);
    this.focusCurrentControl();
  }

  private next(question: AgentQuestion) {
    if (!this.validate(question)) return;
    this.move(this.currentStep + 1);
  }

  private skip(question: AgentQuestion) {
    if (question.required) return;
    this.drafts = {
      ...this.drafts,
      [question.id]: {
        ...(this.drafts[question.id] ?? {
          value: '',
          otherSelected: false,
          otherText: '',
        }),
        skipped: true,
      },
    };
    if (this.currentStep < this.questions.length - 1) this.move(this.currentStep + 1);
    else this.submit();
  }

  private submit() {
    if (this.disabled || this.answerPending) return;
    const invalidIndex = this.questions.findIndex(
      question => !this.validateWithoutFocus(question),
    );
    if (invalidIndex >= 0) {
      this.currentStep = invalidIndex;
      this.focusCurrentControl(true);
      return;
    }

    this.answerPending = true;
    this.dsAnswer.emit({
      requestId: this.requestId,
      answers: this.questions.map(question =>
        normalizeQuestionAnswer(question, this.drafts[question.id]),
      ),
    });
  }

  private validateWithoutFocus(question: AgentQuestion): boolean {
    const message = validateQuestionDraft(question, this.drafts[question.id]);
    if (!message) return true;
    this.validation = { ...this.validation, [question.id]: message };
    return false;
  }

  private progressLabel(): string {
    return this.copy.progress
      .split('{current}')
      .join(String(this.currentStep + 1))
      .split('{total}')
      .join(String(this.questions.length));
  }

  private selectSingle(question: AgentQuestion, value: string) {
    const otherSelected = value === this.otherValue;
    this.updateDraft(question.id, {
      value: otherSelected ? '' : value,
      otherSelected,
    });
    if (otherSelected) {
      requestAnimationFrame(() =>
        this.el.querySelector<HTMLInputElement>('[data-question-other-input]')?.focus(),
      );
    }
  }

  private renderSingleChoice(
    question: AgentQuestion,
    promptId: string,
    errorId: string,
  ) {
    const draft = this.drafts[question.id];
    const value = draft.otherSelected
      ? this.otherValue
      : typeof draft.value === 'string'
        ? draft.value
        : '';
    const options = [
      ...(question.choices ?? []),
      ...(question.allowOther
        ? [{ value: this.otherValue, label: this.copy.other }]
        : []),
    ];
    return (
      <div class="questionnaire__single-choice">
        <ds-radio
          data-question-control
          size="lg"
          options={options}
          value={value}
          disabled={this.disabled}
          form={`ds-agent-questionnaire-detached-${this.instanceId}`}
          ariaLabelledby={promptId}
          aria-describedby={this.validation[question.id] ? errorId : undefined}
          onDsChange={(event: CustomEvent<string>) =>
            this.selectSingle(question, event.detail)
          }
        />
        {draft.otherSelected ? this.renderOtherInput(question, errorId) : null}
      </div>
    );
  }

  private renderMultipleChoice(question: AgentQuestion, errorId: string) {
    const draft = this.drafts[question.id];
    const values = Array.isArray(draft.value) ? draft.value : [];
    const detachedForm = `ds-agent-questionnaire-detached-${this.instanceId}`;
    return (
      <div class="questionnaire__multiple-choice">
        {question.choices?.map(choice => (
          <ds-checkbox
            key={choice.value}
            data-question-control
            size="lg"
            label={choice.label}
            description={choice.description}
            value={choice.value}
            checked={values.includes(choice.value)}
            disabled={this.disabled}
            form={detachedForm}
            onDsChange={(event: CustomEvent<boolean>) => {
              this.updateDraft(question.id, {
                value: event.detail
                  ? [...values, choice.value]
                  : values.filter(value => value !== choice.value),
              });
            }}
          />
        ))}
        {question.allowOther ? (
          <div class="questionnaire__other-choice">
            <ds-checkbox
              data-question-control
              size="lg"
              label={this.copy.other}
              checked={draft.otherSelected}
              disabled={this.disabled}
              form={detachedForm}
              onDsChange={(event: CustomEvent<boolean>) => {
                this.updateDraft(question.id, { otherSelected: event.detail });
                if (event.detail) {
                  requestAnimationFrame(() =>
                    this.el
                      .querySelector<HTMLInputElement>('[data-question-other-input]')
                      ?.focus(),
                  );
                }
              }}
            />
            {draft.otherSelected ? this.renderOtherInput(question, errorId) : null}
          </div>
        ) : null}
      </div>
    );
  }

  private renderOtherInput(question: AgentQuestion, errorId: string) {
    const draft = this.drafts[question.id];
    return (
      <input
        class="questionnaire__other-input"
        data-question-control
        data-question-other-input
        type="text"
        form={`ds-agent-questionnaire-detached-${this.instanceId}`}
        value={draft.otherText}
        placeholder={this.copy.otherPlaceholder}
        aria-label={this.copy.other}
        aria-invalid={this.validation[question.id] ? 'true' : undefined}
        aria-describedby={this.validation[question.id] ? errorId : undefined}
        disabled={this.disabled}
        onInput={(event: Event) =>
          this.updateDraft(question.id, {
            otherText: (event.target as HTMLInputElement).value,
          })
        }
      />
    );
  }

  private renderQuestion(question: AgentQuestion) {
    const draft = this.drafts[question.id];
    const errorId = `ds-agent-questionnaire-${this.instanceId}-${this.currentStep}-error`;
    const promptId = `ds-agent-questionnaire-${this.instanceId}-${this.currentStep}-prompt`;
    return (
      <div class="questionnaire__body">
        <div class="questionnaire__prompt">
          <ds-text as="h2" variant="text-title-small" textId={promptId}>
            {question.question}
          </ds-text>
          {question.description ? (
            <ds-text variant="text-body-small" color="secondary">
              {question.description}
            </ds-text>
          ) : null}
        </div>
        {question.type === 'text' ? (
          <textarea
            class="questionnaire__text-input"
            data-question-control
            value={typeof draft.value === 'string' ? draft.value : ''}
            form={`ds-agent-questionnaire-detached-${this.instanceId}`}
            placeholder={question.placeholder}
            aria-label={question.question}
            aria-invalid={this.validation[question.id] ? 'true' : undefined}
            aria-describedby={this.validation[question.id] ? errorId : undefined}
            disabled={this.disabled}
            rows={4}
            onInput={(event: Event) =>
              this.updateDraft(question.id, {
                value: (event.target as HTMLTextAreaElement).value,
              })
            }
          />
        ) : (
          <fieldset
            class="questionnaire__choices"
            aria-describedby={this.validation[question.id] ? errorId : undefined}
          >
            <legend class="ds-visually-hidden">{question.question}</legend>
            {question.type === 'single'
              ? this.renderSingleChoice(question, promptId, errorId)
              : this.renderMultipleChoice(question, errorId)}
          </fieldset>
        )}
        {this.validation[question.id] ? (
          <div id={errorId} class="questionnaire__error" role="alert">
            <ds-icon name="ErrorTriangle" size="xs" color="inherit" />
            <ds-text variant="text-body-small" color="negative">
              {this.validation[question.id]}
            </ds-text>
          </div>
        ) : null}
      </div>
    );
  }

  private renderAnswered() {
    return (
      <div class="questionnaire questionnaire--answered">
        <ol class="questionnaire__summary">
          {this.questions.map(question => (
            <li>
              <ds-text variant="text-body-small" emphasis>{question.question}</ds-text>
              <ds-text variant="text-body-small" color="secondary">
                {formatQuestionAnswer(
                  question,
                  this.answers.find(answer => answer.questionId === question.id),
                )}
              </ds-text>
            </li>
          ))}
        </ol>
      </div>
    );
  }

  render() {
    if (this.status === 'preparing') {
      return (
        <Host>
          <div class="questionnaire questionnaire--preparing" role="status">
            <ds-loader size="sm" />
            <ds-text variant="text-body-medium">{this.copy.preparing}</ds-text>
          </div>
        </Host>
      );
    }
    if (!this.questions?.length) return null;
    if (this.status === 'answered') return <Host>{this.renderAnswered()}</Host>;

    const question = this.questions[this.currentStep];
    const last = this.currentStep === this.questions.length - 1;
    const canSkip = Boolean(question.skippable && !question.required);
    return (
      <Host>
        <section
          class={{
            questionnaire: true,
            'questionnaire--submitting': this.disabled,
            'questionnaire--error': this.status === 'error',
          }}
          aria-busy={this.disabled ? 'true' : undefined}
          aria-label={question.question}
        >
          <header class="questionnaire__header">
            <ds-text variant="text-caption" color="secondary">{this.progressLabel()}</ds-text>
            {this.allowCancel ? (
              <ds-tooltip label={this.copy.cancel} side="top" size="sm">
                <ds-button-unfilled
                  data-question-action
                  variant="icon"
                  icon="Cross"
                  size="sm"
                  aria-label={this.copy.cancel}
                  hasBorder={false}
                  isInactive={this.disabled}
                  onDsClick={() => this.dsCancel.emit({ requestId: this.requestId })}
                />
              </ds-tooltip>
            ) : null}
          </header>
          {this.renderQuestion(question)}
          {this.status === 'error' && this.errorMessage ? (
            <div class="questionnaire__submission-error" role="alert">
              <ds-icon name="ErrorTriangle" size="xs" color="inherit" />
              <ds-text variant="text-body-small" color="negative">{this.errorMessage}</ds-text>
            </div>
          ) : null}
          <footer class="questionnaire__actions">
            <div class="questionnaire__actions-leading">
              {this.currentStep > 0 ? (
                <div class="questionnaire__action-item">
                  <ds-button-unfilled
                    data-question-action
                    label={this.copy.previous}
                    size="sm"
                    width="fill"
                    isInactive={this.disabled}
                    onDsClick={() => this.move(this.currentStep - 1)}
                  />
                </div>
              ) : null}
              {canSkip ? (
                <div class="questionnaire__action-item">
                  <ds-button-unfilled
                    data-question-action
                    label={this.copy.skip}
                    size="sm"
                    width="fill"
                    hasBorder={false}
                    isInactive={this.disabled}
                    onDsClick={() => this.skip(question)}
                  />
                </div>
              ) : null}
            </div>
            <div class="questionnaire__action-item questionnaire__action-item--primary">
              <ds-button-filled
                data-question-action
                label={last ? this.copy.answer : this.copy.next}
                size="sm"
                width="fill"
                isLoading={this.disabled}
                onDsClick={() => (last ? this.submit() : this.next(question))}
              />
            </div>
          </footer>
        </section>
      </Host>
    );
  }
}

import type {
  AgentQuestion,
  AgentQuestionAnswer,
} from '../conversation-types';

export interface AgentQuestionDraft {
  value: string | string[];
  otherSelected: boolean;
  otherText: string;
  skipped: boolean;
}

export type AgentQuestionDrafts = Record<string, AgentQuestionDraft>;

function answerFor(
  answers: AgentQuestionAnswer[],
  questionId: string,
): AgentQuestionAnswer | undefined {
  return answers.find(answer => answer.questionId === questionId);
}

export function createQuestionnaireDrafts(
  questions: AgentQuestion[],
  answers: AgentQuestionAnswer[],
): AgentQuestionDrafts {
  return Object.fromEntries(
    questions.map(question => {
      const answer = answerFor(answers, question.id);
      const choiceValues = new Set(question.choices?.map(choice => choice.value) ?? []);

      if (question.type === 'multiple') {
        const values = Array.isArray(answer?.value) ? answer.value : [];
        const known = values.filter(value => choiceValues.has(value));
        const other = values.find(value => !choiceValues.has(value)) ?? '';
        return [
          question.id,
          {
            value: known,
            otherSelected: Boolean(question.allowOther && other),
            otherText: question.allowOther ? other : '',
            skipped: answer?.value === null,
          },
        ];
      }

      const value = typeof answer?.value === 'string' ? answer.value : '';
      const isKnownChoice = question.type === 'single' && choiceValues.has(value);
      return [
        question.id,
        {
          value: question.type === 'single' && !isKnownChoice ? '' : value,
          otherSelected: Boolean(
            question.type === 'single' && question.allowOther && value && !isKnownChoice,
          ),
          otherText:
            question.type === 'single' && question.allowOther && value && !isKnownChoice
              ? value
              : '',
          skipped: answer?.value === null,
        },
      ];
    }),
  );
}

export function normalizeQuestionAnswer(
  question: AgentQuestion,
  draft: AgentQuestionDraft,
): AgentQuestionAnswer {
  if (draft.skipped) return { questionId: question.id, value: null };

  if (question.type === 'multiple') {
    const values = Array.isArray(draft.value) ? [...draft.value] : [];
    if (draft.otherSelected && draft.otherText.trim()) values.push(draft.otherText.trim());
    return {
      questionId: question.id,
      value: values.length || question.required ? values : null,
    };
  }

  if (draft.otherSelected) {
    const other = draft.otherText.trim();
    return { questionId: question.id, value: other || null };
  }

  const value = typeof draft.value === 'string' ? draft.value.trim() : '';
  return { questionId: question.id, value: value || null };
}

export function validateQuestionDraft(
  question: AgentQuestion,
  draft: AgentQuestionDraft,
): string | undefined {
  if (
    (question.type === 'single' || question.type === 'multiple') &&
    !question.choices?.length
  ) {
    return 'This question has no available choices.';
  }

  if (draft.otherSelected && !draft.otherText.trim()) {
    return 'Enter a response for Other.';
  }

  if (!question.required || draft.skipped) return undefined;
  const answer = normalizeQuestionAnswer(question, draft).value;
  const missing = answer === null || (Array.isArray(answer) && answer.length === 0);
  if (!missing) return undefined;
  return question.type === 'text'
    ? 'Enter an answer before continuing.'
    : 'Choose an answer before continuing.';
}

export function formatQuestionAnswer(
  question: AgentQuestion,
  answer: AgentQuestionAnswer | undefined,
): string {
  if (!answer || answer.value === null) return 'Skipped';
  const values = Array.isArray(answer.value) ? answer.value : [answer.value];
  const labels = new Map(question.choices?.map(choice => [choice.value, choice.label]) ?? []);
  return values.map(value => labels.get(value) ?? value).join(', ');
}
